fun main() {
    val n = readln().trim().toInt()

    val r: Int
    val r2: Int

    if (n % 2 == 0) {
        r = n / 2 * n / 2
        r2 = n / 2 * n / 2
    } else {
        r = (n + 1) / 2 * ((n + 1) / 2)
        r2 = (n - 1) / 2 * ((n - 1) / 2)
    }

    val t = r + r2

    if (t % 2 == 0) {
        print("2")
    } else {
        print("1")
    }
}

